function drawRings() {
  
  background(10);
  let selectedPalette = getRandomPalette();
  console.log("pallet:", selectedPalette);
  colors = selectedPalette;

  
 
  for (let r = 0; r < radius; r += radius / numRings) {
    let colorIndex = floor(random(colors.length));
    let fillColor = colors[colorIndex];
    
    for (let a = -TAU / numPoints; a < TAU + TAU / numPoints; a += TAU / numPoints) {
      let x1 = width / 2 + r * cos(a);
      let y1 = height / 2 + r * sin(a);

      let x2 = width / 2 + (r + radius / numRings) * cos(a);
      let y2 = height / 2 + (r + radius / numRings) * sin(a);
    
      let n1 = map(noise(x1 * resolution, y1 * resolution ), 0, nv1, -scale, scale);
      let n2 = map(noise(x2 * resolution, y2 * resolution ), 0, nv2, -scale, scale);
  
      stroke(fillColor);
      fill(fillColor);
      line(x1 + n1, y1 + n1, x2 + n2, y2 + n2);

    }
  }

}

